   steps:["A: `/103`: no rule, 404.","B: `/user/103`: `user(\"103\")` finds Rahim and returns the dict as JSON.","C: `/?id=103`: no rule for `/`, 404.","D: `/user?id=103`: `get_user` reads `103` and returns Rahim."],
   optionNotes:{A:{why:"No rule for `/103`.",cause:"Dropping the prefix."},B:{why:"Path form, handled by `user`."},C:{why:"No rule for `/`.",cause:"Thinking the query string alone is enough."},D:{why:"Query form, handled by `get_user`."}},
